insert into public.handlungskompetenz (code, titel, beschreibung, bereich_code, quelle, sortierung) values
  ('a1', 'Bedürfnisse von Stakeholdern im Rahmen eines ICT-Projekts abklären und dokumentieren', 'Informatikerinnen und Informatiker nehmen die Projektziele und Bedürfnisse der Stakeholder auf und dokumentieren diese: Als Erstes erfragen sie die Projektziele und klären übergeordnete Parameter wie Kosten, Zeit, Qualität, Umfang, Verantwortlichkeiten und Methodik (Initiale Road Mapping Session). Sie wenden dabei verschiedene Befragungstechniken und Beobachtungstechniken an (z.B. offene, geschlossene Fragen, Meeting, Workshop, Shadowing, Simulation der anzustrebenden Lösung in Form eines Zeitsprungs). Dank ihres Einfühlungsvermögens sind sie in der Lage, die Bedürfnisse der Stakeholder/der Kundschaft passgenau zu erfassen und das Gespräch zielgerichtet zu führen. Als Nächstes analysieren sie den Systemkontext: Welchen Anforderungen muss das zu entwickelnde System gerecht werden? Sie klären die Systemund Kontextabgrenzung und identifizieren Schnittstellen. Sie erarbeiten Lösungen zur Beseitigung möglicher Zielkonflikte. (Requirements Elicitation) Danach überführen sie die natürlichsprachige Definition (der Stakeholder) in eine modellbasierte Dokumentation und klassifizieren die Projektziele und -anforderungen (z.B. Kano- Modell). Sie achten darauf, allfälligen Interpretationsspielraum zu minimieren. Das Ziel ist es, eindeutige, referenzierbare Projektziele und -anforderungen als Basis für das weitere Vorgehen des Engineering Prozesses zu haben. (Requirements Documentation / Communication) In einem weiteren Schritt überprüfen sie die aufgenommenen Projektziele und -anforderungen bezüglich Messbarkeit, Konsistenz, Vollständigkeit, Notwendigkeit, Korrektheit und Referenzierbarkeit. Dabei setzen sie unterstützende Techniken (z.B. Inspektion, Walkthrough, Perspektivenbasiertes Lesen, Prüfung durch Prototyp) ein. (Requirements Validation) Zuletzt definieren sie die Eigenschaften für die Verwaltung der einzelnen Projektziele und -anforderungen (z.B. Versionierung, Identifikator zur Referenzierbarkeit, Beschreibung, Autor, Quelle, Kritikalität, Priorität). (Requirements Management)', 'a', 'kanton', 1),
  ('a2', 'Vorgehensmodell für ein ICT-Projekt bestimmen', 'Informatikerinnen und Informatiker wählen ein den Projektzielen und -anforderungen entsprechendes Vorgehensmodell: Zunächst analysieren sie die in der Handlungskompetenz a1 ermittelten Parameter und die vom Auftraggeber gegebenen Konditionen (z.B. Teamstruktur, Dynamik der Anforderungen, Entwicklungskultur, Teamgrösse). Danach wägen sie die Vor- und Nachteile von verschiedenen plangetriebenen resp. agilen (iterativen, inkrementellen) Vorgehensmodellen in Bezug auf das ICT-Projekt ab, bewerten diese und wählen ein passendes Modell. Bei Bedarf passen sie das Vorgehensmodell projektspezifisch an (Process-Tailoring).', 'a', 'kanton', 2),
  ('a3', 'Informationen zu ICT-Lösungen und zu Innovationen recherchieren', 'Informatikerinnen und Informatiker suchen gezielt Informationen zu ICT-Lösungen, um Wissenslücken zu schliessen oder den aktuellen Stand der Technik zu erfassen: Sie suchen nach Innovationen, z.B. um eine Übersicht über die Marktsituation zu erstellen oder den aktuellen Stand der Technik zu erfassen. Dazu suchen sie gezielt und systematisch nach Informationen aus digitalen und analogen Quellen. Sie durchleuchten die Ergebnisse kritisch und identifizieren verlässliche und unzuverlässige oder unseriöse Quellen. Sie achten dabei auf Informationen zu Produkten und Lösungen, welche einen sparsamen Umgang mit Energie und einen bedachten Umgang mit verwendeten Ressourcen ermöglichen. Sie tragen mehrere Varianten aus den Ergebnissen zusammen, vergleichen und bewerten sie. Dabei zeigen sie deren technische Potenziale und Risiken auf. Für die favorisierte Variante erstellen sie ein technisches Proof of Concept (PoC), um die prinzipielle Durchführbarkeit eines Vorhabens zu belegen (z.B. zur Risikominimierung).', 'a', 'kanton', 3),
  ('a4', 'ICT-Projekte und daraus entstehende Aufgaben gemäss Vorgehensmodell planen', 'Informatikerinnen und Informatiker planen ihre Aufgaben gemäss dem gewählten Vorgehensmodell: Unabhängig vom Vorgehensmodell brechen sie eine Gesamtaufgabe in kleinere, besser einschätzbare und einer Ressource zuteilbare Aktivitäten herunter (vom Groben zum Detail). Sie unterscheiden Aktivitäten nach Aufwand und Dauer, erstellen eine ungefähre zeitliche Einschätzung und schätzen den Komplexitätsgrad der Aufgabe ab. Weiter klären sie die sequenziellen Abhängigkeiten, definieren die zeitliche Reihenfolge und hinterlegen sie allenfalls mit Ressourcen. Zum Schluss gruppieren und priorisieren sie Aktivitäten zur Erreichung eines Zwischenziels anhand von zeitlichen oder funktionellen Vorgaben und halten dies schriftlich fest. Nachfolgend anhand des Beispiels Scrum «rollenübergreifend» und vereinfacht erklärt: • Sie definieren und priorisieren (z.B. BV, ROI) User Stories im Product Backlog zusammen mit den Stakeholdern. • Sie legen Velocity und Goals (Condition of Satisfaction) für die geplante Iteration (Sprint) fest. • Sie schätzen (Story Points) die User Stories (Story Poker) ab. • Sie bestimmen den Sprint Backlog.', 'a', 'kanton', 4),
  ('a5', 'Varianten für ICT-Lösungen visualisieren und präsentieren', 'Informatikerinnen und Informatiker bereiten verschiedene Varianten von ICT-Lösungen visuell auf und präsentieren sie: Zunächst identifizieren sie die Zielgruppe und deren Informationsbedürfnisse zu den ICT-Lösungen gemäss Anforderungskatalog. Darauf identifizieren sie die zielgruppenrelevanten Merkmale der ICT-Lösungen. Im Anschluss bereiten sie die aus den Merkmalen gewonnenen Erkenntnisse zielgruppen- und problemgerecht visuell auf (z.B. Flipchart, Whiteboard, Präsentationsprogramm, Videoconferencing). Sie nutzen dabei ihre Kreativität und ihr Vorstellungsvermögen. Zum Schluss präsentieren sie ihre Lösungsvorschläge schlüssig und überzeugend, um den Entscheidungsträgern bei ihrer Entscheidungsfindung zu helfen (z.B. durch Storytelling).', 'a', 'kanton', 5),
  ('a6', 'Fortschritt von ICT-Projekten und daraus entstehenden Aufgaben gemäss Vorgehensmodell überprüfen und rapportieren', 'Informatikerinnen und Informatiker überprüfen laufend den Fortschritt eines Projekts oder ihrer Aufgaben darin und rapportieren diesen gemäss projektspezifischem Vorgehensmodell: Entsprechend ihrer Rolle holen oder bringen sie zuerst Bewertungen zum Stand der zugewiesenen Aufträge ein (persönlich oder über ein Tool). Falls sie eine koordinierende oder leitende Rolle im Projekt innehaben, ergeben sich weitere Schritte: Sie sammeln die Bewertungen, kategorisieren und priorisieren sie. Danach konsolidieren sie die Bewertungen und erarbeiten ggf. Vorschläge für Korrekturmassnahmen. In einem weiteren Schritt halten sie den Fortschritt schriftlich fest, visualisieren und kommunizieren ihn. Schliesslich legen sie zusammen mit den Entscheidungsträgern das weitere Vorgehen fest, z.B. Entscheid für Korrekturmassnahmen.', 'a', 'kanton', 6),
  ('a7', 'ICT-Lösungen der Kundin oder dem Kunden übergeben und Projekt abschliessen', 'Informatikerinnen und Informatiker übergeben eine ICT-Lösung der Kundin oder dem Kunden und schliessen das Projekt gemäss Vereinbarung im Projektauftrag ab: Dazu eruieren sie zuerst die einzubeziehenden Personen bei der Kundin bzw. Kunden. Falls noch nicht vorhanden, legen sie zusammen mit der Kundin / dem Kunden die Abnahmekriterien und -verfahren sowie den zeitlichen Ablauf der Übergabe fest. Als Nächstes stellen sie die gemäss Projektauftrag vereinbarte Dokumentation bereit. Bei Bedarf planen sie eine Schulung/Instruktion und bereiten die Schulungsunterlagen vor. Danach führen sie die Abnahme nach den festgelegten Kriterien durch und protokollieren sie. Zum Schluss archivieren und sichern sie ihre Arbeiten nach betriebsspezifischen Vorgaben.', 'a', 'kanton', 7),
  ('b1', 'Den eigenen ICT-Arbeitsplatz einrichten', 'Informatikerinnen und Informatiker richten den eigenen digitalen Arbeitsplatz mit allen benötigten Komponenten ein: In einem ersten Schritt setzen sie den Computer mit einem Betriebssystem auf, verbinden ihn mit einem Netzwerk und testen die Verbindung. Sie konfigurieren die nötigen Sicherheitsmassnahmen (Firewall, Antivirensysteme etc.) gemäss Firmenrichtlinien. Bei Bedarf installieren sie Software, testen, ob sie einwandfrei funktioniert und führen gegebenenfalls Updates aus. Darauf verbinden sie den Computer mit weiteren zu verwendenden Peripheriegeräten und testen deren Funktionalitäten. Des Weiteren richten sie ihren Bürotisch und -stuhl so ein, dass die ergonomischen Grundsätze eingehalten werden. Mit Büromaterialien und Energie gehen sie sparsam um.', 'b', 'kanton', 8),
  ('b2', 'Komplexe ICT-Supportanfragen entgegennehmen und bearbeiten', 'Informatikerinnen und Informatiker nehmen komplexe Supportanfragen entgegen und erarbeiten Lösungen: Sie erhalten im Rahmen des 3rd Level Supports eine Supportanfrage für ein komplexes ICT-Problem. Sie nehmen diese entgegen und beginnen sogleich, den Inhalt der Anfrage systematisch zu analysieren (z.B. mit Hilfe eines Fragenkatalogs oder einer Checkliste). Mittels geeigneter Methoden oder Kollaborationen führen sie eine Lösung herbei und dokumentieren diese nach betriebsspezifischen Vorgaben. Ihre Lösung für die Anfrage bereiten sie zielgruppengerecht (z.B. für den 2nd Level Support) auf und kommunizieren sie dem Anfragesteller.', 'b', 'kanton', 9),
  ('b3', 'Kundinnen und Kunden in Bezug auf Datenschutz und Datensicherheit beraten', 'Informatikerinnen und Informatiker beraten Kundinnen und Kunden im Umgang mit schützenswerten Daten und zeigen Lösungen für Schutzmassnahmen auf: Dazu klären sie zunächst mit gezielten Fragen die Sicherheitssituation bei Kundinnen und Kunden in Bezug auf System, Netzwerk, Software und Daten. Anhand dieser Informationen schlagen sie den Kundinnen und Kunden nötige und empfohlene Schutzmassnahmen in den evaluierten Bereichen vor. Sie schaffen ein Bewusstsein für Gefahren im Netz und im Umgang mit schützenswerten Daten. Zur Erfüllung dieser Aufgaben informieren sie sich laufend über Veränderungen der rechtlichen Rahmenbedingungen/Vorgaben. Bei Bedarf schulen sie Mitarbeitende in der Anwendung der firmeneigenen IT-Richtlinien.', 'b', 'kanton', 10),
  ('b4', 'Geschäftsprozesse von Kundinnen und Kunden analysieren, visualisieren und dokumentieren', 'Informatikerinnen und Informatiker analysieren Geschäftsprozesse, stellen sie grafisch dar und dokumentieren sie: In einem ersten Schritt identifizieren sie relevante Prozessinformationen (Bezeichnung, auslösendes Ereignis, Ergebnis, Auslöser, Empfänger). Darauf zerlegen sie die Geschäftsprozesse in einer Aufgabenanalyse in einzelne Prozessschritte. Nun dokumentieren sie den Prozessablauf und stellen ihn auf der Basis von anerkannten und üblichen Beschreibungsstandards grafisch dar. In einem weiteren Schritt präzisieren sie den Prozessablauf mit Zusatzinformationen wie benötigten Hilfsmitteln, ausführenden Stellen sowie der Beschreibung des zu erzeugenden Outputs (Ergebnis). Zum Schluss übergeben sie die Dokumentation dem Kunden.', 'b', 'kanton', 11),
  ('c1', 'Daten identifizieren, analysieren und Datenmodelle entwickeln', 'Informatikerinnen und Informatiker analysieren Daten aus verschiedenen Datenquellen und fassen sie in einem geeigneten Datenmodell zusammen: Je nach Auftrag erhalten sie Daten aus verschiedenen strukturierten und unstrukturierten Datenquellen. Als Erstes sichten sie die Daten und ordnen sie hinsichtlich des 4V-Modells ein (volume, variety, velocity, veracity). Als Nächstes untersuchen sie die Daten auf Eindeutigkeit und Widersprüchlichkeit und bereinigen sie falls nötig. In einem weiteren Schritt gewinnen sie Indikatoren/Anhaltspunkte für die Modellbildung aus bestehenden Auswertungsformen (Reports). Sie bestimmen je nach Datentyp geeignete Testfälle für die Datenkorrektheit sowie eine geeignete Struktur für die bereinigten Daten. Schliesslich normalisieren sie das Datenmodell und bilden es in geeigneter Darstellung ab.', 'c', 'kanton', 12),
  ('c2', 'Datenmodelle in einem digitalen Datenspeicher umsetzen', 'Informatikerinnen und Informatiker realisieren ein Datenmodell in einem geeigneten digitalen Datenspeicher: Dazu wählen sie zuerst einen geeigneten Datenspeicher (z.B. objektrelational, relational, verteilt/zentral). Nun implementieren sie ein normalisiertes Datenmodell für die Speicherung und berücksichtigen dabei die referentielle Integrität. Als Nächstes planen sie Funktions- und Performancetests und bereiten die dazu notwendigen Testdaten vor. Sie führen die Funktions- und Performancetests durch und werten sie aus. Weiter planen sie Datenmigrationen aus unterschiedlichen Quellsystemen in ein Zielsystem und führen sie durch. Sie prüfen die migrierten Daten im Zielsystem auf Vollständigkeit, Integrität und Korrektheit.', 'c', 'kanton', 13),
  ('c3', 'Datensicherheit und Datenschutz für ICT-Lösungen planen, implementieren und dokumentieren', 'Informatikerinnen und Informatiker planen Massnahmen zur Datensicherheit und zum Datenschutz, implementieren sie und dokumentieren sie: In einem ersten Schritt identifizieren sie schutzwürdige Daten und kategorisieren sie. Als Nächstes modellieren sie die schützenswerten Daten gemäss Privacy by design. Sie klären die erforderlichen Schutzmechanismen gemäss Schutzwürdigkeit ab und qualifizieren sie. Dabei berücksichtigen sie die gesetzlichen Rahmenbedingungen (u.a. DSGVO) und interpretieren sie situationsgerecht. Darauf erarbeiten sie ein Datensicherheits- und Rollenkonzept gemäss Auftrag, dokumentieren es und setzen es um (z.B. Backup erstellen, Zugriffsberechtigung setzen, Daten verschlüsseln). Zuletzt überprüfen sie die eingerichteten Datensicherheits- und Schutzmechanismen in Bezug auf ihre Wirksamkeit.', 'c', 'kanton', 14),
  ('c4', 'Daten aus digitalen Datenspeichern aufbereiten', 'Informatikerinnen und Informatiker analysieren Daten aus digitalen Datenspeichern und bereiten sie auf: Zu Beginn lesen sie die Daten in eine geeignete Analysesoftware ein. Darauf führen sie eine explorative Datenanalyse durch und identifizieren mögliche Datenfehler. Sie prüfen die Validität der aufbereiteten Daten durch Stichproben. Als Nächstes vergleichen sie etablierte Aufbereitungsmethoden und Darstellungsformen miteinander und bewerten sie. Auf dieser Grundlage wählen sie geeignete Darstellungsformen aus und setzen sie ein (z.B. logarithmieren und nicht lineare Zusammenhänge linear darstellen). Schliesslich stellen sie die Daten anonymisiert bereit (z.B. für Testfälle).', 'c', 'kanton', 15),
  ('d1', 'ICT-Prozesse aufnehmen, standardisieren und automatisieren', 'Informatikerinnen und Informatiker nehmen ICT-Prozesse (z.B. Benutzermanagement, Service Provisionierung, Loganalysen) auf, standardisieren und automatisieren diese. Damit erreichen sie eine Erhöhung der Effizienz und Qualität für die implementierten ICT-Prozesse: In einem ersten Schritt holen sie die Anforderungen der Stakeholder in Bezug auf geschäfts- und/oder betriebsrelevante ICT-Prozesse ein. Dies geschieht beispielsweise im Rahmen eines Beratungsgesprächs (a1). Auf dieser Grundlage leiten sie einen technischen Lösungsvorschlag ab und halten diesen schriftlich fest. Sie berücksichtigen dabei insbesondere betriebliche Gegebenheiten und Standards (z.B. BPMN, Orchestrierungstools, Scheduling-Tools, OS-builds). Den Lösungsvorschlag setzen sie schliesslich um. Schrittweise führen sie die Automatisierung der definierten Prozesse durch. Dazu setzen sie Scriptsprachen, Infrastructure as Code (IaC) und/oder Automatisierungsframeworks ein. Sie halten sich an empfohlene Vorgehensweisen und berücksichtigen dabei Best Practices.', 'd', 'kanton', 16),
  ('d2', 'Auslieferungsprozess von ICT-Lösungen definieren', 'Informatikerinnen und Informatiker definieren den Prozess, mit welchem entwickelte ICT-Lösungen dem Kunden ausgeliefert werden. Damit erreichen sie eine professionelle und den Anforderungen entsprechende Auslieferung der ICT-Lösung: Zunächst identifizieren sie bereits bestehende Auslieferungsprozesse (z.B. Software Deployment und HW-Rollout) unter Einbezug der betroffenen Schnittstellen und Stakeholdern. Sie bestimmen eine geeignete Plattform und/oder nötige Erweiterungen und Anpassungen. Den definitiven Auslieferungsprozess dokumentieren sie schriftlich und kommunizieren diesen allen betroffenen Stellen. Ausserdem erstellen sie ein Testkonzept für die Auslieferung (z.B. Funktions- und Integrationstests) und berücksichtigen dabei mögliche Sicherheitsrisiken (z.B. Hardware-Life Cycle, Absicherung der Datenübermittlung, Sicherheitskonzept der Einzelkomponenten).', 'd', 'kanton', 17),
  ('d3', 'Ausführungsplattform für ICT-Lösungen vorbereiten', 'Informatikerinnen und Informatiker bereiten eine Ausführungsplattform für ICT-Lösungen vor: Sie stellen die definierte Ausführungsplattform (gemäss d2) bereit (z.B. Continuous delivery toolchain, Virtualisierungsplattform). Dabei pflegen sie einen engen und proaktiven Austausch mit relevanten Projektbeteiligten. Weiter konfigurieren sie die Plattform gemäss den geplanten Anforderungen. Sie dokumentieren die vorgenommenen Schritte und Einstellungen nachvollziehbar. Abschliessend überprüfen sie, ob die vorbereitete Plattform abgenommen werden kann.', 'd', 'kanton', 18),
  ('d4', 'ICT-Lösungen in Betrieb nehmen', 'Informatikerinnen und Informatiker nehmen ICT-Lösungen gemäss Anforderungen in Betrieb. Damit stellen sie eine erfolgreiche Übergabe an den Auftraggeber sicher: Je nach Projekt beantragen sie die erforderlichen Zugriffsrechte wie auch Berechtigungen für die Inbetriebnahme. Falls notwendig koordinieren sie die Anpassungen an den Umsystemen. Danach führen sie die Inbetriebnahme durch (z.B. Ausführung von Deployment-Scripts, Rollout). Sie sind in regelmässigem Austausch mit den Stakeholdern und informieren diese über den Fortschritt der Inbetriebnahme. Sie testen die entsprechende Lösung gemäss Testkonzept (d2). Schliesslich überprüfen sie die Lösung auf Sicherheitsrisiken. Die umgesetzte ICT-Lösung übergeben sie dem Auftraggeber. Bei Bedarf führen sie eine Schulung durch oder erstellen eine Dokumentation (vgl. a7).', 'd', 'kanton', 19),
  ('e1', 'Netze planen und dokumentieren', 'Informatikerinnen und Informatiker planen bestehende oder neue IP-Netze für unterschiedlichste Auftraggeber (Kleinstbetrieb bis Grossunternehmen) und führen die nötigen Dokumentationen nach. Damit schaffen sie nachvollziehbare Grundlagen für den Aufbau und Betrieb der Netze: Zunächst nehmen sie bei relevanten Stakeholdern (z.B. Auftraggeber, interne Abteilung, Hersteller) die Anforderungen auf (z.B. Verfügbarkeit, Sicherheit) (vgl. a1). Aufgrund der Anforderungen leiten sie einen ersten Vorschlag oder Lösungsvarianten ab. Sie berücksichtigen dabei je nach Situation betriebliche Gegebenheiten, technische Standards oder rechtliche Vorgaben. Sie halten den Vorschlag schriftlich fest. In einem nächsten Schritt nehmen sie das Detaildesign vor: Sie konzipieren die geeignete Netzinfrastruktur (LAN) unter Berücksichtigung der räumlichen Verhältnisse und Vorgaben (z.B. Bandbreite, Übertragungsmedien, erforderlichen Dienst-Verfügbarkeit und Sicherheit). Die physische und logische Netzstruktur dokumentieren sie systematisch und achten darauf, dass sie alle relevanten Angaben erfasst haben. Weiter evaluieren sie mögliche Internetdienstanbieter (ISP) gemäss den Netzanforderungen, wählen einen Anbieter aus und halten die Angaben inkl. Kostenvarianten im Konzept fest. Schliesslich erstellen sie eine Testkonzept zur Überprüfung der Funktionalität, Performance und Sicherheit des Netzes.', 'e', 'kanton', 20),
  ('e2', 'Netzkomponenten auswählen und in Betrieb nehmen', 'Auf der Grundlage der erfolgten Netzplanung (e1) wählen Informatikerinnen und Informatiker geeignete Netzkomponenten aus und nehmen diese in Betrieb: Zunächst führen sie eine Recherche durch und bestimmen die geeigneten Netzkomponenten. Sie erstellen eine Materialliste gemäss internem Bestellprozess und den Budgetvorgaben. Die bestellten Netzkomponenten überprüfen sie beim Eingang auf Vollständigkeit. In der Regel erstellen sie ein Konzept für die Konfiguration. In einem nächsten Schritt nehmen sie die Netzkomponenten in Betrieb. Häufig setzen sie die Netzkomponenten zunächst firmenintern auf, nehmen Vorkonfigurationen und Upgrades vor und führen eine erste Funktionskontrolle durch. Anschliessend installieren sie die Netzkomponenten vor Ort beim Kunden. Sie führen eine Endkonfiguration durch und testen die Funktionsfähigkeit des Netzes gemäss dem erstellten Konzept. Je nach Situation übergeben sie das installierte Netz dem Kunden, informieren diesen und führen ihn bei Bedarf ein.', 'e', 'kanton', 21),
  ('e3', 'Netze warten und weiterentwickeln', 'Informatikerinnen und Informatiker warten Netze im Rahmen von Wartungsaufträgen und entwickeln die Netze bei Bedarf weiter (Continuous Service Improvement): In den definierten Wartungsintervallen führen sie vor Ort Sichtkontrollen der Netzkomponenten durch. Auf dieser Grundlage entscheiden sie, ob Massnahmen notwendig sind (z.B. Entstauben). Weiter führen sie die Log-Überprüfung der Komponenten durch (z.B. Temperaturschwankungen, Durchflussraten, Performanceraten, Auslastungen, Fehlermeldungen). Bei Bedarf treffen sie Massnahmen für die kurzfristige oder langfristige Weiterentwicklung (z.B. zusätzliche Komponente, Umkonzipierung des Netzes, Konfiguration anpassen, Patches und Upgrades). Sie führen nötige Updates und Upgrades der Komponenten sowie allfällige weitere Wartungsarbeiten (z.B. Firmware Update) durch. Die ausgeführten Wartungsarbeiten und Empfehlungen dokumentieren sie sorgfältig. Bei Bedarf klären sie grössere Massnahmen mit Vorgesetzten und Auftraggebern ab. Dabei sind sie sich des Life Cycles von Netzwerkkomponenten bewusst und können darüber informieren, wann diese voraussichtlich ersetzt werden müssen. Sie berücksichtigen ausserdem ökologische Kriterien, wie z.B. Energie Labels oder Nachhaltigkeit. Bei allen Wartungsarbeiten achten sie auf einen sorgfältigen Umgang mit den Geräten und treffen Massnahmen, um diese vor elektrostatischen Entladungen zu schützen.', 'e', 'kanton', 22),
  ('e4', 'Sicherheit von Netzen implementieren, dokumentieren und überprüfen', 'Informatikerinnen und Informatiker implementieren, dokumentieren und überprüfen die Sicherheit von Netzen. Damit stellen sie sicher, dass kritische Systeme bedarfsgerecht vor Angriffen oder Schädlingsbefall geschützt werden: Zunächst analysieren sie mögliche Sicherheitsrisiken eines Netzes und bewerten diese. Dazu verwenden sie aktuelle und betriebsspezifische Tools (z.B. Portscanner). Auf dieser Grundlage konzipieren sie physische und systemische Sicherheitsmassnahmen im lokalen Netz (e1). Sie setzen die geplanten Sicherheitsmassnahmen um, indem sie sicherheitsrelevante Dienste und Komponenten implementieren (z.B. Firewall, VPN, NAT, VLAN, DMZ). Anschliessend testen sie die Sicherheitsmassnahmen systematisch und dokumentieren deren Funktionalität.', 'e', 'kanton', 23),
  ('e5', 'Leistungsfähigkeit eines Netzes analysieren, optimieren und dokumentieren', 'Informatikerinnen und Informatiker analysieren, optimieren und dokumentieren die Leistungsfähigkeit eines Netzes. Dies geschieht typischerweise im laufenden Betrieb, in regelmässigen Zyklen oder wenn Probleme gemeldet werden (z.B. Monitoring, Usermeldungen): Nach der Kontaktaufnahme und Problemschilderung (z.B. Start einer Applikation ist langsam) durch einen Stakeholder klären sie zunächst mögliche Ursachen ab. Sie analysieren die Netzauslastung (LAN) und legen anschliessend Lösungsvarianten fest (z.B. Loadbalancing, QoS, PoE). Sie berücksichtigen dabei verschiedene Faktoren, wie z.B. die Auswirkung der Verkabelung auf die Leistungsfähigkeit. Sie dokumentieren die gewählte Lösung und passen die Konfiguration der entsprechenden Komponenten (z.B. Switch, Router, Access Point) an. Sie testen abschliessend die Funktionsfähigkeit des Netzes. Falls erforderlich, schlagen sie dem Stakeholder eine Auswechslung oder Erweiterung der Komponenten vor (→e1).', 'e', 'kanton', 24),
  ('e6', 'Netze überwachen', 'Informatikerinnen und Informatiker überwachen Netze kontinuierlich. Damit gewährleisten sie einen lückenlosen Netzbetrieb und erkennen Probleme, Störungen und Verbesserungsmöglichkeiten frühzeitig: Anhand verschiedener Monitoring-Tools überwachen sie Netze kontinuierlich, entweder für ihr Unternehmen oder für Kunden im Rahmen einer Dienstleistungsvereinbarung (SLA). Sie kontrollieren insbesondere Verfügbarkeit und Funktionsfähigkeit der Netzkomponenten. Ausserdem überwachen sie die Auslastung des Netzes (z.B. Performance von Komponenten und Übertragungsstrecken). Sie schätzen die Dringlichkeit von eingehenden Meldungen/Alarmierungen ab und treffen zum richtigen Zeitpunkt geeignete Massnahmen (Trouble Shooting). Sie grenzen den Fehler auf Ebene der Komponenten ein. Sie gehen strukturiert und hartnäckig vor, bis der Fehler identifiziert werden kann. Schliesslich organisieren sie die Fehlerbehebung im Team oder mit externen Partnern.', 'e', 'kanton', 25),
  ('f1', 'Serversysteme und -dienste planen und dokumentieren', 'Informatikerinnen und Informatiker planen Serversysteme und Serverdienste für unterschiedlichste Auftraggeber (Kleinstbetrieb bis Grossunternehmen) und führen die nötigen Dokumentationen nach. Damit schaffen sie nachvollziehbare Grundlagen für den Aufbau und Betrieb der Systeme und Dienste: Zunächst nehmen sie bei relevanten Stakeholdern (z.B. Auftraggeber, interne Abteilung, Hersteller) die Anforderungen an benötigte Funktionen, sowie das vorgesehene Budget auf (→a1). Aufgrund der Anforderungen leiten sie einen ersten Vorschlag oder Lösungsvarianten für mögliche Serversysteme und/oder Serverdienste (z.B. Webdienste, Datenbanken, Datenspeicherdienste, Data Analytics) ab. Sie berücksichtigen dabei je nach Situation betriebliche Gegebenheiten, technische Standards, rechtliche Vorgaben sowie den IT-Grundschutz. Sie beraten die Stakeholder, klären deren Fragen und hinterfragen Anforderungen kritisch. Sie halten die Lösungsvarianten mit den Anforderungen schriftlich fest. In einem nächsten Schritt bestimmen sie die geeignete Plattform (z.B. inhouse VM, Cloud, Hybridsystem, Container) sowie die dazugehörenden Leistungsparameter (z.B. OS, CPU, Memory, Storage, Networking). Sie wenden dazu messbare Bewertungskriterien an. Wenn nötig wählen sie geeignete Hard- und Software aus. Sie denken dabei vorausschauend und beachten die Rahmenbedingungen, wie z.B. die Vorgabe eines Herstellers, Einsatz- und Einbaumöglichkeiten oder die Stromversorgung und die Energieeffizienz. Weiter definieren sie die erforderlichen Dienste und legen die benötigten Ressourcen (z.B. Serverressourcen, Cloud Services, Lizenzen, Berechtigungen, SSO) fest. Dabei berücksichtigen sie relevante Abhängigkeiten, wie z.B. clientseitige Kompatibilitäten (Browser, Ciphers). Sie nehmen eine gesamtheitliche Perspektive ein und bedenken mögliche Auswirkungen. Schliesslich erstellen sie ein Testkonzept, um bei der Inbetriebnahme Funktionalität, Performance und Sicherheit der Systeme und Dienste zu prüfen.', 'f', 'kanton', 26),
  ('f2', 'Serversysteme in Betrieb nehmen', 'Informatikerinnen und Informatiker nehmen geplante Serversysteme in Betrieb (unter Serversystemen werden Hardware, virtuelle Maschinen oder Container verstanden, welche entweder inhouse oder cloudbasiert sind): Liegt der definitive Umsetzungsentscheid für ein Serversystem vor, beschaffen sie die benötigten Komponenten und/oder Ressourcen (z.B. Personell, Material, Infrastruktur, Lizenzen, Cloud Services). Schliesslich nehmen sie die Komponenten und/oder Services in Betrieb, indem sie diese aufsetzen und konfigurieren. Sie gehen dabei gemäss der definierten Planung vor und berücksichtigen interne Anforderungen, Richtlinien und Best Practices. Sie prüfen das Serversystem mit den geplanten Tests (→f1) und überführen dieses in den Produktivbetrieb.', 'f', 'kanton', 27),
  ('f3', 'Serverdienste in Betrieb nehmen', 'Informatikerinnen und Informatiker nehmen geplante Serverdienste in Betrieb (zu Serverdiensten zählen z.B. DNS, Webserver, Datenbank, JRE, Kollaborationsplattform, IoT Gateway, Messenging Bus, Big Data Analytics): Liegt der definitive Umsetzungsentscheid für einen Serverdienst vor, beschaffen sie die benötigten Ressourcen (z.B. Personell, Lizenzen, Cloud Services). In einem nächsten Schritt nehmen sie die Services in Betrieb, indem sie diese gemäss den Anforderungen installieren und konfigurieren. Sie gehen dabei gemäss der definierten Planung vor und berücksichtigen interne Anforderungen, Richtlinien und Best Practices. Sie prüfen den Service mit den geplanten Tests und überführen diesen in den Produktivbetrieb. Schliesslich führen sie das Betriebshandbuch nach und übergeben es dem Auftraggeber.', 'f', 'kanton', 28),
  ('f4', 'Serversysteme und -dienste warten und verwalten', 'Informatikerinnen und Informatiker warten Serversysteme und Serverdienste und verwalten diese. Damit stellen sie einen kontinuierlichen produktiven Betrieb sicher: Je nach Anforderungen des Systems oder des Dienstes definieren sie zunächst die Wartungsaufgaben und deren Wartungszyklus (täglich / wöchentlich / monatlich / bei bestimmten Ereignissen, gemäss SLA). Sie führen die Wartungsaufgaben zu den definierten Zeitpunkten zuverlässig durch und dokumentieren diese. Werden Updates benötigt (z.B. Upgrades, Patches, Firmware) testen sie diese und spielen sie in der Produktivumgebung ein. Weiter testen sie Funktionalität, Performance und Sicherheit von Systemen und Diensten in regelmässigen Zyklen. Werden Änderungen an den Systemen vorgenommen, dokumentieren sie diese übersichtlich. Sie gehen diszipliniert vor und achten darauf, dass Eingriffe auf Systemen und Diensten jederzeit nachvollziehbar sind. Ausserdem sind sie sich ihrer Schweigepflicht bewusst und gehen mit Daten vertrauensvoll und sorgfältig um.', 'f', 'kanton', 29),
  ('f5', 'Serversysteme und -dienste überwachen', 'Informatikerinnen und Informatiker überwachen Serversysteme und Serverdienste. Damit erkennen sie Probleme frühzeitig und können Ausfallrisiken minimieren: Mit den jeweiligen Stakeholdern definieren sie zunächst, welche Serversysteme und Serverdienste überwacht werden sollen. Anschliessend bestimmen sie geeignete Überwachungsmethoden (Script, Software, Benachrichtigungen etc.). Weiter legen sie Schwellenwerte und Aktionen fest, welche bei Über-/Unterschreitung der Schwellenwerte durchgeführt werden sollen. Dabei schätzen sie die jeweiligen Risiken aufgrund ihrer Erfahrungen sowie entsprechend den Anforderungen des Auftraggebers oder den Dienstleistungsvereinbarungen (SLA) ab. Ist die Überwachung in Betrieb, überprüfen sie mit periodischen Tests, ob das Überwachungssystem zuverlässig funktioniert. Die Ergebnisse dokumentieren sie nachvollziehbar. Bei Fehlermeldungen oder Alarmmeldungen handeln sie rasch und ergreifen entsprechende Massnahmen.', 'f', 'kanton', 30),
  ('f6', 'Sicherheit von Serversystemen und -diensten implementieren, dokumentieren und überprüfen', 'Informatikerinnen und Informatiker implementieren, dokumentieren und überprüfen die Sicherheit von Serversystemen und Serverdiensten: Zunächst erstellen sie gemäss den Anforderungen der Stakeholder ein Sicherheitskonzept. Dieses beschreibt mögliche Risiken sowie geeignete Sicherheitssysteme/-methoden für den IT-Grundschutz (z.B. Firewall, Antiviren Software, Berechtigungen, SSO). Sie arbeiten dabei im Team und ziehen bei Bedarf Partner bei. Sie beachten Best Practices der eingesetzten Lösungen. Sie konfigurieren die definierten Sicherheitselemente und testen anschliessend deren Wirksamkeit. Im laufenden Betrieb führen sie in regelmässigen Zyklen Sicherheitstests durch. Die Ergebnisse dokumentieren sie nachvollziehbar. Sie informieren sich regelmässig über technologische Entwicklungen von Sicherheitssystemen (z.B. MELANI, CVE) und passen ihre Sicherheitskonzepte entsprechend an.', 'f', 'kanton', 31),
  ('f7', 'Verfügbarkeit von Serversystemen und -diensten planen und umsetzen', 'Informatikerinnen und Informatiker planen die Verfügbarkeit von Serversystemen und Serverdiensten. Sie setzen Massnahmen um, um die Vorgaben zu Datenverlusten und Ausfallzeiten einzuhalten: Im Gespräch mit ihren Stakeholdern eruieren sie den verkraftbaren Datenverlust (Recovery Point Objective), den verkraftbaren Ausfall von Serversystemen und Serverdiensten (Recovery Time Objective) sowie Datenvorhaltefristen (Backup Retention). Sie halten die Ergebnisse in Form einer Dokumentation schriftlich fest. In einem nächsten Schritt überprüfen sie die aktuellen Systeme und Dienste anhand der Beschaffenheit oder Dienstleistungsvereinbarungen (SLA) und halten fest, wo die Verfügbarkeit noch nicht gewährleistet ist. Sie entscheiden über eventuelle Anpassungen und definieren mögliche Lösungen/Optimierungen. Besonders gefragt sind hierbei ihre Analyse- und Konzeptionsfähigkeit. Die Optimierungsmassnahmen besprechen sie mit den Stakeholdern und holen deren Einwilligung zur Freigabe ein. Schliesslich setzen sie die Lösungen/Optimierungen um: Sie nehmen die geplanten Anpassungen in der Umgebung vor. Sie testen in regelmässigen Abständen, ob die Verfügbarkeit der Systeme und Daten den definierten Anforderungen entsprechen.', 'f', 'kanton', 32),
  ('f8', 'Backup- und Archivierungskonzepte für Daten erstellen und umsetzen', 'Informatikerinnen und Informatiker erstellen Backup- und Archivierungskonzepte für Daten und setzen diese um. Sie stellen damit sicher, dass Daten nachhaltig verfügbar sind: Sie legen gemeinsam mit den Stakeholdern fest, welche Daten (z.B. Benutzer-, Konfiguration-, System-, Logdaten) gesichert und archiviert werden sollen. Danach erstellen sie ein Backup (inkl. Recovery- und Desaster-Recovery-Konzept) und/oder Archivierungskonzept. Dabei nehmen sie eine gesamtheitliche Betrachtung ein: Sie berücksichtigen den Sicherungszyklus, Datenvorhaltefristen sowie Anforderungen an die Compliance. Weiter definieren sie relevante Aspekte, wie z.B. Periodizität, Grösse, Art des Mediums, Berechtigungen und Zugriffe. Ausserdem berücksichtigen sie rechtliche Vorgaben bezüglich Datenschutzes (z.B. DSVGO). In regelmässigen Abständen überprüfen sie, ob die Wiederherstellung der Daten und Services einwandfrei funktioniert. Sie dokumentieren die Test-Ergebnisse nachvollziehbar.', 'f', 'kanton', 33);
