  ((select id from public.handlungskompetenz where code = 'a1' and quelle = 'kanton'), 'a1.4', 'Sie erarbeiten Lösungen zur Beseitigung möglicher Zielkonflikte.', 'K5', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 4),
