  ((select id from public.handlungskompetenz where code = 'a1' and quelle = 'kanton'), 'a1.6', 'Sie überprüfen die Projektziele und -anforderungen bezüglich Messbarkeit, Konsistenz, Vollständigkeit, Notwendigkeit, Korrektheit und Referenzierbarkeit.', 'K4', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 6),
  ((select id from public.handlungskompetenz where code = 'a1' and quelle = 'kanton'), 'a1.7', 'Sie definieren die Eigenschaften für die Verwaltung der einzelnen Projektziele und -anforderungen (z.B. Versionierung, Identifikator zur Referenzierbarkeit, Beschreibung, Autor, Quelle, Kritikalität, Priorität).', 'K3', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 7),
