  ((select id from public.handlungskompetenz where code = 'a2' and quelle = 'kanton'), 'a2.3', 'Sie passen ein Vorgehensmodell projektspezifisch an (Process-Tailoring).', 'K5', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 10),
