  ((select id from public.handlungskompetenz where code = 'a4' and quelle = 'kanton'), 'a4.3', 'Sie schätzen Aufwand, Dauer und Komplexitätsgrad von Aktivitäten ab.', 'K4', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 18),
  ((select id from public.handlungskompetenz where code = 'a4' and quelle = 'kanton'), 'a4.4', 'Sie klären die sequenziellen Abhängigkeiten von Aktivitäten und definieren die zeitliche Reihenfolge.', 'K4', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 19),
