  ((select id from public.handlungskompetenz where code = 'a5' and quelle = 'kanton'), 'a5.2', 'Sie identifizieren die zielgruppenrelevanten Merkmale einer ICT-Lösung.', 'K4', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 22),
  ((select id from public.handlungskompetenz where code = 'a5' and quelle = 'kanton'), 'a5.3', 'Sie bereiten die aus den Merkmalen gewonnenen Erkenntnisse zielgruppen- und problemgerecht visuell auf (z.B. Flipchart, Whiteboard, Präsentationsprogramm, Videoconferencing).', 'K5', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 23),
