  ((select id from public.handlungskompetenz where code = 'a6' and quelle = 'kanton'), 'a6.1', 'Sie bringen Bewertungen zum Stand der ihnen zugewiesenen Aufträge ein (persönlich oder über ein Tool).', 'K3', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 25),
  ((select id from public.handlungskompetenz where code = 'a6' and quelle = 'kanton'), 'a6.2', 'Sie kategorisieren und priorisieren gesammelte Bewertungen.', 'K4', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 26),
  ((select id from public.handlungskompetenz where code = 'a6' and quelle = 'kanton'), 'a6.3', 'Sie konsolidieren die Bewertungen und erarbeiten ggf. Vorschläge für Korrekturmassnahmen.', 'K5', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 27),
  ((select id from public.handlungskompetenz where code = 'a6' and quelle = 'kanton'), 'a6.4', 'Sie halten den Fortschritt schriftlich fest und stellen ihn visuell dar.', 'K3', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 28),
  ((select id from public.handlungskompetenz where code = 'a6' and quelle = 'kanton'), 'a6.5', 'Sie rapportieren die zusammengefassten Ergebnisse zum Projektfortschritt gemäss projektspezifischem Vorgehensmodell.', 'K3', '431: Aufträge im eigenen Umfeld selbstständig durchführen 306: Kleinprojekt im eigenen Berufsumfeld abwickeln', 29),
